                        // Index 5: Invoices
                        InvoiceHistoryView(
                          estimates: _estimates,
                          items: _items,
                          customers: _customers,
                          onEditInvoice: _onLoadInvoiceToEdit,
                          onRefreshRequired: () => _fetchData(silent: true),
                        ),
                        // Index 6: Reports
                        EnterpriseReportsView(
                          estimates: _estimates,
                          items: _items,
                          customers: _customers,
                          onEditInvoice: _onLoadInvoiceToEdit,
                          onRefreshRequired: () => _fetchData(silent: true),
                        ),
                        // Index 7: Settings
                        SettingsDesktopView(
                          onReloadSheet: () => _fetchData(silent: true),
