            onPressed: () async {
              Navigator.pop(ctx);
              await http.post(
                Uri.parse(sheetApiUrl),
                body: jsonEncode({
                  "action": "CANCEL_ESTIMATE",
                  "rowIndex": est.rowIndex,
                }),
              );
              widget.onRefreshRequired();
            },
            child: const Text('YES (Cancel Bill)', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
