        boxShadow: [
          BoxShadow(
            color: const Color(0xFF0284C7).withOpacity(0.45),
            blurRadius: 28,
            spreadRadius: 4,
          ),
        ],
      ),
      child: Stack(
        alignment: Alignment.center,
        children: [
          Icon(Icons.shield_rounded, size: size * 0.76, color: const Color(0xFF132D4B)),
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'SP',
                style: TextStyle(
                  fontSize: size * 0.36,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.5,
                  foreground: Paint()
                    ..shader = const LinearGradient(
                      colors: [Colors.white, Color(0xFF67E8F9), Color(0xFF0284C7)],
                    ).createShader(Rect.fromLTWH(0, 0, size, size * 0.4)),
                  shadows: const [
                    Shadow(color: Colors.black, blurRadius: 8, offset: Offset(0, 2)),
                  ],
                ),
              ),
              Text(
                'MultiBill ERP',
                style: TextStyle(
                  fontSize: size * 0.10,
                  fontWeight: FontWeight.bold,
                  letterSpacing: 0.8,
                  color: const Color(0xFFE0F2FE),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return Scaffold(
        backgroundColor: const Color(0xFF0B1015),
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              _buildShieldLogoWidget(size: 130),
              const SizedBox(height: 28),
              const Text('SP MULTIBILL ERP',
                  style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold, letterSpacing: 1.5, color: Color(0xFFF8FAFC))),
              const SizedBox(height: 6),
              const Text('POWERED BY SP TECH SOLUTIONS',
                  style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600, letterSpacing: 2.0, color: Color(0xFF38BDF8))),
              const SizedBox(height: 4),
              const Text('Wholesale, Retail & Distribution Suite • v3.8.0',
                  style: TextStyle(fontSize: 11, color: Color(0xFF94A3B8))),
              const SizedBox(height: 36),
              const SizedBox(
                width: 170,
                child: LinearProgressIndicator(
                  minHeight: 3,
                  backgroundColor: Color(0xFF131922),
                  valueColor: AlwaysStoppedAnimation<Color>(Color(0xFF0284C7)),
                ),
              ),
            ],
          ),
        ),
      );
    }

    return FocusScope(
      onKeyEvent: (node, event) {
        if (event is KeyDownEvent) {
          if (event.logicalKey == LogicalKeyboardKey.escape && _navIndex != 0) {
            setState(() => _navIndex = 0);
            return KeyEventResult.handled;
          }
        }
        return KeyEventResult.ignored;
      },
      child: Scaffold(
        body: Column(
          children: [
            if (_isBackgroundSyncing)
              const LinearProgressIndicator(
                minHeight: 3,
                backgroundColor: Color(0xFF131922),
                valueColor: AlwaysStoppedAnimation<Color>(Color(0xFF1E88E5)),
              ),
            Expanded(
              child: Row(
                children: [
                  NavigationRail(
                    selectedIndex: _navIndex,
                    onDestinationSelected: (val) => setState(() => _navIndex = val),
                    labelType: NavigationRailLabelType.all,
                    leading: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 14),
