class DCItem {

  int rowIndex;

  dynamic no;

  String name;

  String rateType;

  String rate;

  dynamic qty;

  String tallyName;

  String billedIn;

  bool isTaxable;



  DCItem({

    required this.rowIndex,

    required this.no,

    required this.name,

    required this.rateType,

    required this.rate,

    required this.qty,

    required this.tallyName,

    required this.billedIn,

    required this.isTaxable,

  });



  factory DCItem.fromJson(Map<String, dynamic> json) {

    return DCItem(

      rowIndex: json['rowIndex'] ?? 0,

      no: json['no'] ?? '',

      name: json['name'] ?? '',

      rateType: json['rateType'] ?? '',

      rate: json['rate']?.toString() ?? '0',

      qty: json['qty'] ?? '',

      tallyName: json['tallyName'] ?? '',

      billedIn: json['billedIn'] ?? '',

      isTaxable: json['isTaxable'] ?? false,

    );

  }

}



class DCCustomer {

  int rowIndex;

  dynamic slNo;

  String name;

  String contact;

  String address;

  String b2c;

  String b2b;

  String remarks;



  DCCustomer({

    required this.rowIndex,

    required this.slNo,

    required this.name,

    required this.contact,

    required this.address,

    required this.b2c,

    required this.b2b,

    required this.remarks,

  });



  factory DCCustomer.fromJson(Map<String, dynamic> json) {

    return DCCustomer(

      rowIndex: json['rowIndex'] ?? 0,

      slNo: json['slNo'] ?? '',

      name: json['name'] ?? '',

      contact: json['contact']?.toString() ?? '',

      address: json['address']?.toString() ?? '',

      b2c: json['b2c'] ?? '',

      b2b: json['b2b'] ?? '',

      remarks: json['remarks'] ?? '',

    );

  }



  String get billingTag {

    final r = remarks.toUpperCase();

    if (r.contains('CREDIT')) return 'CREDIT';

    if (r.contains('VAZHI BILL') || r.contains('VAZHIBILL')) return 'VAZHI BILL';

    if (r.contains('NO COOLI')) return 'NO COOLI';

    return 'REGULAR';

  }

}



