                          const Text('Current Date', style: TextStyle(fontWeight: FontWeight.w600)),
                          Text(_spFullDate(DateTime.now())),
                          const SizedBox(height: 16),
                          const Text('Current Period', style: TextStyle(fontWeight: FontWeight.w600)),
