                      children: [
                        Center(child: _buildShieldLogoWidget(size: 70)),
                        const SizedBox(height: 12),
                        const Center(child: Text('SP MULTIBILL ERP', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 16))),
