                        const SizedBox(height: 16),
                        const Divider(),
                        const SizedBox(height: 10),
                        const Text('Current Date', style: TextStyle(fontWeight: FontWeight.w600, fontSize: 12)),
                        Text(_spFullDate(DateTime.now()), style: const TextStyle(fontSize: 13)),
                        const SizedBox(height: 12),
                        const Text('Current Period', style: TextStyle(fontWeight: FontWeight.w600, fontSize: 12)),
                        Text(
                          '${_spDate(DateTime(DateTime.now().month >= 4 ? DateTime.now().year : DateTime.now().year - 1, 4, 1))} – ${_spDate(DateTime(DateTime.now().month >= 4 ? DateTime.now().year + 1 : DateTime.now().year, 3, 31))}',
                          style: const TextStyle(fontSize: 13),
                        ),
                        const Spacer(),
                        OutlinedButton.icon(
                          onPressed: _openCompanyProfileDialog,
                          icon: const Icon(Icons.edit_outlined, size: 16),
                          label: const Text('Company Setup'),
                        ),
                      ],
                    ),
                  ),
                  // Right Collapsible Menu Panel
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(20, 16, 20, 16),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Text('Gateway Menu', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w800)),
                              const Spacer(),
                              Text('Click sections to expand or collapse', style: TextStyle(fontSize: 12, color: scheme.onSurfaceVariant)),
                            ],
                          ),
                          const SizedBox(height: 10),
                          const Divider(),
                          Expanded(
                            child: ListView(
                              children: categories.entries.map((cat) {
                                final isTransactions = cat.key == 'TRANSACTIONS';
                                return Card(
                                  margin: const EdgeInsets.symmetric(vertical: 5),
                                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                                  color: scheme.surfaceContainerHighest.withOpacity(0.35),
                                  child: Theme(
                                    data: Theme.of(context).copyWith(dividerColor: Colors.transparent),
